import os
from dataclasses import dataclass
from functools import lru_cache
from typing import Any, Dict, Optional

from openai import OpenAI


@dataclass(frozen=True)
class ObservabilityConfig:
    api_key: str
    base_url: str
    query_model: str
    ingest_model: str
    organization: Optional[str] = None
    project: Optional[str] = None


def _env(name: str, default: Optional[str] = None) -> Optional[str]:
    value = os.getenv(name)
    return value if value not in (None, "") else default


def load_config() -> ObservabilityConfig:
    api_key = _env("OPENAI_API_KEY") or ""
    base_url = _env("OPENAI_BASE_URL", "https://api.openai.com/v1")
    query_model = _env("OBSERVABILITY_QUERY_MODEL", "gpt-5.4-mini")
    ingest_model = _env("OBSERVABILITY_INGEST_MODEL", "gpt-5.4-mini")
    organization = _env("OPENAI_ORG_ID")
    project = _env("OPENAI_PROJECT")
    return ObservabilityConfig(
        api_key=api_key,
        base_url=base_url,
        query_model=query_model,
        ingest_model=ingest_model,
        organization=organization,
        project=project,
    )


@lru_cache(maxsize=1)
def get_client() -> OpenAI:
    config = load_config()
    kwargs: Dict[str, Any] = {"api_key": config.api_key, "base_url": config.base_url}
    if config.organization:
        kwargs["organization"] = config.organization
    if config.project:
        kwargs["project"] = config.project
    return OpenAI(**kwargs)


def get_query_model() -> str:
    return load_config().query_model


def get_ingest_model() -> str:
    return load_config().ingest_model


def get_default_headers() -> Dict[str, str]:
    return {"X-Observability-Client": "managed-log-query"}


def reset_client_cache() -> None:
    get_client.cache_clear()

import os
from datetime import datetime, timedelta, timezone

import requests


def _isoformat_utc(dt):
    return dt.astimezone(timezone.utc).isoformat().replace('+00:00', 'Z')


def fetch_recent_logs(field_name, field_value, minutes=60, limit=100):
    api_key = os.environ.get('DATADOG_API_KEY')
    app_key = os.environ.get('DATADOG_APP_KEY')
    site = os.environ.get('DATADOG_SITE', 'datadoghq.com')
    if not api_key or not app_key:
        raise RuntimeError('DATADOG_API_KEY and DATADOG_APP_KEY are required')

    now = datetime.now(timezone.utc)
    start = now - timedelta(minutes=minutes)
    query = f'@{field_name}:{field_value}'
    payload = {
        'filter': {
            'from': _isoformat_utc(start),
            'to': _isoformat_utc(now),
            'query': query,
        },
        'page': {'limit': limit},
        'sort': 'desc',
    }
    response = requests.post(
        f'https://api.{site}/api/v2/logs/events/search',
        headers={
            'DD-API-KEY': api_key,
            'DD-APPLICATION-KEY': app_key,
            'Content-Type': 'application/json',
        },
        json=payload,
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


if __name__ == '__main__':
    print(fetch_recent_logs('service', 'api'))

import os
from datetime import datetime, timedelta, timezone

import requests


BETTERSTACK_API_BASE = "https://api.betterstack.com"


def _api_token() -> str:
    token = os.getenv("BETTERSTACK_API_TOKEN") or os.getenv("LOGTAIL_API_KEY")
    if not token:
        raise RuntimeError("Missing BETTERSTACK_API_TOKEN or LOGTAIL_API_KEY")
    return token


def _source_id() -> str:
    source_id = os.getenv("BETTERSTACK_SOURCE_ID") or os.getenv("LOGTAIL_SOURCE_ID")
    if not source_id:
        raise RuntimeError("Missing BETTERSTACK_SOURCE_ID or LOGTAIL_SOURCE_ID")
    return source_id


def _parse_time(value: str | None, fallback: datetime) -> datetime:
    if not value:
        return fallback
    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def query_error_logs(severity: str = "error", start_time: str | None = None, end_time: str | None = None, limit: int = 100):
    end_dt = _parse_time(end_time, datetime.now(timezone.utc))
    start_dt = _parse_time(start_time, end_dt - timedelta(hours=24))
    response = requests.get(
        f"{BETTERSTACK_API_BASE}/v1/sources/{_source_id()}/query",
        headers={"Authorization": f"Bearer {_api_token()}"},
        params={
            "query": f'severity:"{severity}"',
            "start_dt": start_dt.isoformat(),
            "end_dt": end_dt.isoformat(),
            "limit": limit,
        },
        timeout=30,
    )
    response.raise_for_status()
    data = response.json()
    return data.get("data", data)


if __name__ == "__main__":
    import json
    import sys

    severity = sys.argv[1] if len(sys.argv) > 1 else "error"
    start_time = sys.argv[2] if len(sys.argv) > 2 else None
    end_time = sys.argv[3] if len(sys.argv) > 3 else None
    print(json.dumps(query_error_logs(severity=severity, start_time=start_time, end_time=end_time), indent=2))

